/**
 * Actify UI Core Library
 * Component-based UI system for modern web applications
 * @version 1.0.0
 * @license MIT
 */

class ActifyUI {
  constructor(options = {}) {
    // Default configuration
    this.config = {
      theme: 'light',
      prefix: 'act-',
      components: [
        'button',
        'modal',
        'dropdown',
        'toast',
        'tooltip',
        'tabs',
        'accordion'
      ],
      ...options
    };

    // Registered components
    this.components = new Map();
    this.instances = new WeakMap();
    this.styleElement = null;

    // Initialize
    this.init();
  }

  /**
   * Initialize the UI system
   */
  init() {
    // Inject base styles
    this.injectBaseStyles();

    // Register default components
    this.config.components.forEach(component => {
      this.registerComponent(component);
    });

    // Auto-initialize components in the DOM
    if (this.config.autoInit !== false) {
      this.autoInitComponents();
    }
  }

  /**
   * Inject base styles into the document
   */
  injectBaseStyles() {
    this.styleElement = document.createElement('style');
    this.styleElement.textContent = this.getBaseStyles();
    document.head.appendChild(this.styleElement);
  }

  /**
   * Generate base styles for components
   */
  getBaseStyles() {
    return `
      [data-actify-component] {
        visibility: hidden;
      }
      
      .${this.config.prefix}btn {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 0.5rem 1rem;
        border-radius: 0.25rem;
        font-weight: 500;
        cursor: pointer;
        transition: all 0.2s ease;
        user-select: none;
        border: 1px solid transparent;
      }
      
      .${this.config.prefix}btn-primary {
        background-color: var(--primary);
        color: white;
      }
      
      .${this.config.prefix}modal {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: rgba(0,0,0,0.5);
        opacity: 0;
        pointer-events: none;
        transition: opacity 0.3s ease;
        z-index: 1000;
      }
      
      .${this.config.prefix}modal.active {
        opacity: 1;
        pointer-events: all;
      }
      
      .${this.config.prefix}modal-content {
        background-color: white;
        border-radius: 0.5rem;
        max-width: 90%;
        max-height: 90%;
        overflow: auto;
      }
    `;
  }

  /**
   * Register a new component type
   * @param {string} name - Component name
   * @param {Object} [implementation] - Component implementation
   */
  registerComponent(name, implementation) {
    if (this.components.has(name)) {
      console.warn(`Component ${name} is already registered`);
      return;
    }

    if (implementation) {
      this.components.set(name, implementation);
    } else {
      // Load default implementation
      const defaultImpl = this.getDefaultComponent(name);
      if (defaultImpl) {
        this.components.set(name, defaultImpl);
      } else {
        console.warn(`No default implementation found for component ${name}`);
      }
    }
  }

  /**
   * Get default component implementation
   */
  getDefaultComponent(name) {
    const components = {
      button: ButtonComponent,
      modal: ModalComponent,
      dropdown: DropdownComponent,
      toast: ToastComponent,
      tooltip: TooltipComponent,
      tabs: TabsComponent,
      accordion: AccordionComponent
    };
    
    return components[name];
  }

  /**
   * Initialize a component on a DOM element
   */
  initComponent(element) {
    const componentName = element.dataset.actifyComponent;
    if (!componentName || !this.components.has(componentName)) {
      return null;
    }

    const ComponentClass = this.components.get(componentName);
    const instance = new ComponentClass(element, this.config);
    this.instances.set(element, instance);
    element.style.visibility = 'visible';
    return instance;
  }

  /**
   * Auto-initialize components in the DOM
   */
  autoInitComponents() {
    document.querySelectorAll('[data-actify-component]').forEach(element => {
      this.initComponent(element);
    });

    // Watch for dynamically added components
    if (typeof MutationObserver !== 'undefined') {
      this.observer = new MutationObserver(mutations => {
        mutations.forEach(mutation => {
          mutation.addedNodes.forEach(node => {
            if (node.nodeType === 1) { // Element node
              if (node.hasAttribute('data-actify-component')) {
                this.initComponent(node);
              }
              node.querySelectorAll('[data-actify-component]').forEach(el => {
                this.initComponent(el);
              });
            }
          });
        });
      });

      this.observer.observe(document.body, {
        childList: true,
        subtree: true
      });
    }
  }

  /**
   * Create a new component instance programmatically
   */
  create(componentName, options = {}) {
    if (!this.components.has(componentName)) {
      throw new Error(`Component ${componentName} is not registered`);
    }

    const element = document.createElement('div');
    element.dataset.actifyComponent = componentName;
    
    // Apply options as data attributes
    Object.entries(options).forEach(([key, value]) => {
      if (key !== 'content') {
        element.dataset[key] = typeof value === 'object' ? JSON.stringify(value) : value;
      }
    });

    // Set content if provided
    if (options.content) {
      if (typeof options.content === 'string') {
        element.innerHTML = options.content;
      } else {
        element.appendChild(options.content);
      }
    }

    document.body.appendChild(element);
    return this.initComponent(element);
  }

  /**
   * Set the theme (light/dark)
   */
  setTheme(theme) {
    this.config.theme = theme;
    document.documentElement.setAttribute('data-theme', theme);
    this.dispatchEvent('themechange', { theme });
  }

  /**
   * Toggle between light/dark theme
   */
  toggleTheme() {
    this.setTheme(this.config.theme === 'light' ? 'dark' : 'light');
  }

  /**
   * Event system
   */
  on(event, callback) {
    document.addEventListener(`actify:${event}`, callback);
    return this;
  }

  dispatchEvent(event, detail = {}) {
    document.dispatchEvent(new CustomEvent(`actify:${event}`, { 
      detail: { ...detail, ui: this }
    }));
  }
}

// Base Component Class
class ActifyComponent {
  constructor(element, config) {
    this.element = element;
    this.config = config;
    this.prefix = config.prefix;
    this.initialized = false;
    this.init();
  }

  init() {
    // To be implemented by specific components
    this.initialized = true;
  }

  show() {
    this.element.style.display = '';
  }

  hide() {
    this.element.style.display = 'none';
  }

  destroy() {
    // Cleanup event listeners and references
    this.element.remove();
  }
}

// Button Component
class ButtonComponent extends ActifyComponent {
  init() {
    this.element.classList.add(`${this.prefix}btn`);
    
    // Add variant class if specified
    const variant = this.element.dataset.variant || 'primary';
    this.element.classList.add(`${this.prefix}btn-${variant}`);
    
    // Add loading state handler
    if (this.element.dataset.loading) {
      this.element.addEventListener('click', () => {
        this.setLoading(true);
      });
    }
    
    super.init();
  }

  setLoading(isLoading) {
    if (isLoading) {
      this.element.innerHTML = `<span class="${this.prefix}btn-spinner"></span> ${this.element.textContent}`;
      this.element.disabled = true;
    } else {
      const spinner = this.element.querySelector(`.${this.prefix}btn-spinner`);
      if (spinner) {
        spinner.remove();
      }
      this.element.disabled = false;
    }
  }
}

// Modal Component
class ModalComponent extends ActifyComponent {
  init() {
    this.element.classList.add(`${this.prefix}modal`);
    this.content = this.element.querySelector(`.${this.prefix}modal-content`) || 
                   this.createModalContent();
    
    // Close on backdrop click
    this.element.addEventListener('click', (e) => {
      if (e.target === this.element) {
        this.hide();
      }
    });
    
    // Close button
    const closeBtn = this.element.querySelector('[data-modal-close]');
    if (closeBtn) {
      closeBtn.addEventListener('click', () => this.hide());
    }
    
    super.init();
  }

  createModalContent() {
    const content = document.createElement('div');
    content.className = `${this.prefix}modal-content`;
    content.innerHTML = this.element.innerHTML;
    this.element.innerHTML = '';
    this.element.appendChild(content);
    return content;
  }

  show() {
    this.element.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  hide() {
    this.element.classList.remove('active');
    document.body.style.overflow = '';
  }

  toggle() {
    this.element.classList.contains('active') ? this.hide() : this.show();
  }
}

// Dropdown Component
class DropdownComponent extends ActifyComponent {
  init() {
    this.trigger = this.element.querySelector(`.${this.prefix}dropdown-trigger`) || 
                  this.element.firstElementChild;
    this.menu = this.element.querySelector(`.${this.prefix}dropdown-menu`);
    
    if (!this.menu) {
      console.warn('Dropdown menu element not found');
      return;
    }
    
    this.menu.style.display = 'none';
    
    // Toggle on trigger click
    this.trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggle();
    });
    
    // Close when clicking outside
    document.addEventListener('click', () => {
      this.hide();
    });
    
    super.init();
  }

  show() {
    this.menu.style.display = 'block';
  }

  hide() {
    this.menu.style.display = 'none';
  }

  toggle() {
    this.menu.style.display === 'none' ? this.show() : this.hide();
  }
}

// Toast Component
class ToastComponent extends ActifyComponent {
  init() {
    this.element.classList.add(`${this.prefix}toast`);
    
    // Auto-hide if duration is set
    const duration = parseInt(this.element.dataset.duration) || 3000;
    if (duration > 0) {
      setTimeout(() => {
        this.hide();
      }, duration);
    }
    
    // Close button
    const closeBtn = this.element.querySelector('[data-toast-close]');
    if (closeBtn) {
      closeBtn.addEventListener('click', () => this.hide());
    }
    
    super.init();
  }

  show() {
    this.element.style.display = 'block';
  }

  hide() {
    this.element.style.opacity = '0';
    setTimeout(() => {
      this.destroy();
    }, 300);
  }
}

// Tooltip Component
class TooltipComponent extends ActifyComponent {
  init() {
    this.element.classList.add(`${this.prefix}tooltip`);
    this.tooltip = this.element.querySelector(`.${this.prefix}tooltip-content`);
    
    if (!this.tooltip) {
      console.warn('Tooltip content element not found');
      return;
    }
    
    this.tooltip.style.display = 'none';
    
    this.element.addEventListener('mouseenter', () => this.show());
    this.element.addEventListener('mouseleave', () => this.hide());
    
    super.init();
  }

  show() {
    this.tooltip.style.display = 'block';
  }

  hide() {
    this.tooltip.style.display = 'none';
  }
}

// Tabs Component
class TabsComponent extends ActifyComponent {
  init() {
    this.tabs = Array.from(this.element.querySelectorAll(`.${this.prefix}tab`));
    this.panels = Array.from(this.element.querySelectorAll(`.${this.prefix}tab-panel`));
    
    if (this.tabs.length === 0 || this.panels.length === 0) {
      console.warn('Tabs or panels not found');
      return;
    }
    
    // Activate first tab by default
    this.activateTab(this.tabs[0]);
    
    // Add click handlers
    this.tabs.forEach(tab => {
      tab.addEventListener('click', () => this.activateTab(tab));
    });
    
    super.init();
  }

  activateTab(tab) {
    // Deactivate all tabs and panels
    this.tabs.forEach(t => t.classList.remove('active'));
    this.panels.forEach(p => p.style.display = 'none');
    
    // Activate selected tab
    tab.classList.add('active');
    const panelId = tab.dataset.target;
    const panel = document.getElementById(panelId);
    if (panel) {
      panel.style.display = 'block';
    }
  }
}

// Accordion Component
class AccordionComponent extends ActifyComponent {
  init() {
    this.items = Array.from(this.element.querySelectorAll(`.${this.prefix}accordion-item`));
    
    if (this.items.length === 0) {
      console.warn('Accordion items not found');
      return;
    }
    
    // Add click handlers to headers
    this.items.forEach(item => {
      const header = item.querySelector(`.${this.prefix}accordion-header`);
      const content = item.querySelector(`.${this.prefix}accordion-content`);
      
      if (!header || !content) continue;
      
      content.style.display = 'none';
      
      header.addEventListener('click', () => {
        const isOpen = content.style.display === 'block';
        content.style.display = isOpen ? 'none' : 'block';
        item.classList.toggle('active', !isOpen);
      });
    });
    
    super.init();
  }
}

// Export as global and module
if (typeof window !== 'undefined') {
  window.ActifyUI = ActifyUI;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = ActifyUI;
}
